// Animated council busts (original art, generated by assets/pixel/composed/scripts/characters_council.py).
// Each sheet is 128x96: columns = 4 frames, rows = idle / talk / think. Import as modules so Vite fingerprints them.
import chill from '../../../../../assets/pixel/composed/characters/cast-chill/bust.png';
import grind from '../../../../../assets/pixel/composed/characters/cast-grind/bust.png';
import advisor from '../../../../../assets/pixel/composed/characters/cast-advisor/bust.png';
import chair from '../../../../../assets/pixel/composed/characters/cast-chair/bust.png';

export type CastName = 'chill' | 'grind' | 'advisor' | 'chair';
export type CastState = 'idle' | 'talk' | 'think';

export const BUST_SHEETS: Readonly<Record<CastName, string>> = { chill, grind, advisor, chair };
export const CAST_STATE_ROW: Readonly<Record<CastState, number>> = { idle: 0, talk: 1, think: 2 };
export const CAST_DISPLAY: Readonly<Record<CastName, string>> = {
  chill: 'Chill',
  grind: 'Grind',
  advisor: 'Advisor',
  chair: 'Chairman',
};
/** Plain-words state label, shown next to the avatar so state is never colour only. */
export const CAST_STATE_LABEL: Readonly<Record<CastState, string>> = {
  idle: 'Listening',
  talk: 'Speaking',
  think: 'Thinking',
};

/** 'Chairman' | 'chair' | 'CHILL' -> 'chair' | 'chill'; unknown names return undefined. */
export function castName(input: string): CastName | undefined {
  const k = input.trim().toLowerCase();
  if (k === 'chairman' || k === 'chair') return 'chair';
  return k === 'chill' || k === 'grind' || k === 'advisor' ? k : undefined;
}
